  --text-muted: #64748b;
  --primary: #4f46e5;
  --primary-600: #4338ca;
  --danger: #dc2626;
  --danger-600: #b91c1c;
  --danger-soft: #fee2e2;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.04), 0 1px 3px rgba(15, 23, 42, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(15, 23, 42, 0.1), 0 25px 50px -12px rgba(15, 23, 42, 0.25);
  --radius: 14px;
  --radius-sm: 10px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }

/* Top bar */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 28px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}

.brand { display: flex; align-items: center; gap: 10px; font-weight: 600; }
.logo-dot {
  width: 22px; height: 22px; border-radius: 7px;
  background: linear-gradient(135deg, #6366f1, #06b6d4);
  box-shadow: var(--shadow-sm);
}
.brand-name { letter-spacing: -0.01em; }
.brand-accent { color: var(--text-muted); font-weight: 500; }

.topnav { display: flex; gap: 6px; }
.topnav a {
  padding: 8px 14px;
  border-radius: 8px;
  color: var(--text-muted);
  font-weight: 500;
  transition: background .15s, color .15s;
}
.topnav a:hover { background: var(--surface-2); color: var(--text); }
.topnav a.active { background: #eef2ff; color: var(--primary); }

.avatar {
  width: 34px; height: 34px;
  border-radius: 50%;
  background: linear-gradient(135deg, #f59e0b, #ef4444);
  color: white;
  display: grid; place-items: center;
  font-size: 12px; font-weight: 600;
}

/* Page */
.page {
  max-width: 1080px;
  margin: 0 auto;
  padding: 28px 24px 80px;
}

.breadcrumbs {
  display: flex; align-items: center; gap: 8px;
  color: var(--text-muted);
  font-size: 13px;
  margin-bottom: 18px;
}
.breadcrumbs a:hover { color: var(--text); }
.breadcrumbs .sep { opacity: 0.5; }
.breadcrumbs .current { color: var(--text); font-weight: 500; }

/* Preview card */
.preview-card {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  gap: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

@media (max-width: 820px) {
  .preview-card { grid-template-columns: 1fr; }
}

.preview-image {
  background: #0f172a;
  aspect-ratio: 4/3;
  position: relative;
  overflow: hidden;
}
.preview-image img {
  width: 100%; height: 100%;
  object-fit: cover;
  display: block;
}
.image-fallback {
  position: absolute; inset: 0;
  display: grid; place-items: center;
  color: white;
  background: linear-gradient(135deg, #1e293b, #475569);
  font-weight: 600;
  letter-spacing: 0.05em;
}

.preview-meta {
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.meta-head h1 {
  margin: 0 0 4px;
  font-size: 22px;
  letter-spacing: -0.01em;
}
.subtitle { margin: 0; color: var(--text-muted); font-size: 13px; }

.meta-list {
  margin: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 24px;
}
.meta-list > div { display: flex; flex-direction: column; gap: 2px; }
.meta-list dt { color: var(--text-muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.04em; }
.meta-list dd { margin: 0; font-weight: 500; }

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
  padding-top: 18px;
  border-top: 1px solid var(--border);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 14px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  font-size: 14px;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  transition: background .15s, color .15s, border-color .15s, transform .05s;
  background: transparent;
  color: var(--text);
}
.btn:active { transform: translateY(1px); }
.btn:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.btn-ghost {
  background: var(--surface-2);
  border-color: var(--border);
  color: var(--text);
}
.btn-ghost:hover { background: #eef0f5; }

.btn-danger {
  background: var(--danger);
  color: white;
}
.btn-danger:hover { background: var(--danger-600); }

/* Modal */
.modal[hidden] { display: none; }

.modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 20px;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.55);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  animation: fade-in .18s ease-out;
}

.modal-panel {
  position: relative;
  background: var(--surface);
  border-radius: 16px;
  box-shadow: var(--shadow-lg);
  width: 100%;
  max-width: 440px;
  padding: 28px;
  animation: panel-in .22s cubic-bezier(.2,.8,.2,1);
}

@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes panel-in {
  from { opacity: 0; transform: translateY(8px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

.modal-close {
  position: absolute;
  top: 12px; right: 12px;
  width: 32px; height: 32px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  display: grid; place-items: center;
  cursor: pointer;
  transition: background .15s, color .15s;
}
.modal-close:hover { background: var(--surface-2); color: var(--text); }
.modal-close:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }

.modal-icon {
  width: 48px; height: 48px;
  border-radius: 50%;
  background: var(--danger-soft);
  color: var(--danger);
  display: grid; place-items: center;
  margin-bottom: 16px;
}

.modal-title {
  margin: 0 0 6px;
  font-size: 18px;
  letter-spacing: -0.01em;
}

.modal-desc {
  margin: 0 0 22px;
  color: var(--text-muted);
  font-size: 14px;
}
.modal-desc strong { color: var(--text); font-weight: 600; }

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

/* Toast */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: #0f172a;
  color: #fff;
  padding: 10px 16px;
  border-radius: 10px;
  font-size: 14px;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s, transform .2s;
  z-index: 200;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
