  --bg: #f6f7fb;
  --surface: #ffffff;
  --surface-2: #fafbfd;
  --border: #e6e8ef;
  --text: #0f172a;
  --text-muted: #64748b;
  --primary: #4f46e5;
  --primary-600: #4338ca;
  --danger: #dc2626;
  --danger-600: #b91c1c;
  --danger-soft: #fee2e2;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.04), 0 1px 3px rgba(15, 23, 42, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(15, 23, 42, 0.1), 0 25px 50px -12px rgba(15, 23, 42, 0.25);
  --radius: 14px;
  --radius-sm: 10px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }

/* Top bar */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 28px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}

.brand { display: flex; align-items: center; gap: 10px; font-weight: 600; }
.logo-dot {
  width: 22px; height: 22px; border-radius: 7px;
  background: linear-gradient(135deg, #6366f1, #06b6d4);
  box-shadow: var(--shadow-sm);
}
.brand-name { letter-spacing: -0.01em; }
.brand-accent { color: var(--text-muted); font-weight: 500; }

.topnav { display: flex; gap: 6px; }
.topnav a {
  padding: 8px 14px;
  border-radius: 8px;
  color: var(--text-muted);
  font-weight: 500;
  transition: background .15s, color .15s;
}
.topnav a:hover { background: var(--surface-2); color: var(--text); }
.topnav a.active { background: #eef2ff; color: var(--primary); }

.avatar {
  width: 34px; height: 34px;
  border-radius: 50%;
  background: linear-gradient(135deg, #f59e0b, #ef4444);
  color: white;
  display: grid; place-items: center;
  font-size: 12px; font-weight: 600;
}

/* Page */
.page {
  max-width: 1080px;
  margin: 0 auto;
  padding: 28px 24px 80px;
}

.breadcrumbs {
  display: flex; align-items: center; gap: 8px;
  color: var(--text-muted);
  font-size: 13px;
  margin-bottom: 18px;
}
.breadcrumbs a:hover { color: var(--text); }
.breadcrumbs .sep { opacity: 0.5; }
.breadcrumbs .current { color: var(--text); font-weight: 500; }

/* Preview card */
.preview-card {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  gap: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

@media (max-width: 820px) {
  .preview-card { grid-template-columns: 1fr; }
}

.preview-image {
  background: #0f172a;
  aspect-ratio: 4/3;
  position: relative;
  overflow: hidden;
}
.preview-image img {
  width: 100%; height: 100%;
  object-fit: cover;
  display: block;
}
.image-fallback {
  position: absolute; inset: 0;
  display: grid; place-items: center;
  color: white;
  background: linear-gradient(135deg, #1e293b, #475569);
  font-weight: 600;
  letter-spacing: 0.05em;
}

.preview-meta {
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.meta-head h1 {
  margin: 0 0 4px;
  font-size: 22px;
  letter-spacing: -0.01em;
}
.subtitle { margin: 0; color: var(--text-muted); font-size: 13px; }

.meta-list {
  margin: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 24px;
}
.meta-list > div { display: flex; flex-direction: column; gap: 2px; }
.meta-list dt { color: var(--text-muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.04em; }
.meta-list dd { margin: 0; font-weight: 500; }

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
  padding-top: 18px;
  border-top: 1px solid var(--border);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
